/* Model Secure stack guard inputs on the host. The build defines the Arm
   feature macro to select the CMSE check (MISRA C:2023 Rule 21.2 deviation).
   The register bank and address-check result are ordinary host data.  */

#include <assert.h>

#include "tx_api.h"
#include "tx_secure_interface.h"
#include "tx_thread_secure_stack_registers.h"
#include "arm_cmse.h"

#ifndef TX_MAX_SECURE_CONTEXTS
#define TX_MAX_SECURE_CONTEXTS     32U
#endif

#define TEST_SECURE_STACK_SIZE     256UL

ULONG test_secure_registers[TEST_REGISTER_COUNT];

static UINT register_writes;
static UINT range_access_allowed = TX_TRUE;
static TX_THREAD owner;
static TX_THREAD unowned;

/* Record a register write for the rejected-path assertions.  */
VOID test_secure_register_write(TEST_SECURE_REGISTER reg, ULONG value)
{
    test_secure_registers[reg] = value;
    register_writes++;
}

/* Model clearing the simulated active stack.  */
VOID test_secure_stack_clear(VOID)
{
    test_secure_register_write(TEST_REGISTER_PSPLIM, 0UL);
    test_secure_register_write(TEST_REGISTER_PSP, 0UL);
}

/* Check the requested range and supply the simulated address-check decision.  */
VOID *cmse_check_address_range(VOID *address, size_t size, int flags)
{
    assert(size == sizeof(TX_THREAD));
    assert(flags == (CMSE_NONSECURE | CMSE_MPU_READWRITE));
    return((range_access_allowed == TX_TRUE) ? address : TX_NULL);
}

/* The host test uses one thread and has no asynchronous interrupts.  */
UINT _tx_thread_interrupt_disable(VOID)
{
    return(0U);
}

/* Restore the simulated interrupt posture.  */
VOID _tx_thread_interrupt_restore(UINT posture)
{
    assert(posture == 0U);
}

/* Check that rejecting a context leaves the active stack registers untouched.  */
static VOID check_context_rejected(TX_THREAD *thread_ptr, UINT expected)
{
    UINT writes_before = register_writes;

    assert(_tx_thread_secure_mode_stack_free(thread_ptr) == expected);
    _tx_thread_secure_stack_context_save(thread_ptr);
    _tx_thread_secure_stack_context_restore(thread_ptr);
    assert(register_writes == writes_before);
}

/* Check that a rejected save leaves the saved stack position intact.  */
static VOID check_stack_save_rejected(ULONG simulated_psp, ULONG expected_psp)
{
    UINT writes_before = register_writes;

    test_secure_registers[TEST_REGISTER_PSP] = simulated_psp;
    _tx_thread_secure_stack_context_save(&owner);
    assert(register_writes == writes_before);
    _tx_thread_secure_stack_context_restore(&owner);
    assert(test_secure_registers[TEST_REGISTER_PSP] == expected_psp);
}

/* Run the Secure-side guard cases with real context bookkeeping and simulated hardware.  */
int main(void)
{
    ULONG stack_top;

    assert(_tx_thread_secure_mode_stack_initialize() == TX_CALLER_ERROR);
    assert(_tx_thread_secure_mode_stack_allocate(&owner, TEST_SECURE_STACK_SIZE) == TX_CALLER_ERROR);
    check_context_rejected(&owner, TX_CALLER_ERROR);

    test_secure_registers[TEST_REGISTER_IPSR] = 1UL;
    assert(_tx_thread_secure_mode_stack_initialize() == TX_SUCCESS);
    assert(_tx_thread_secure_mode_stack_allocate(&owner, TEST_SECURE_STACK_SIZE) == TX_SUCCESS);
    _tx_thread_secure_stack_context_restore(&owner);
    stack_top = test_secure_registers[TEST_REGISTER_PSP];
    assert(stack_top != 0UL);

    range_access_allowed = TX_FALSE;
    assert(_tx_thread_secure_mode_stack_allocate(&unowned, TEST_SECURE_STACK_SIZE) == TX_PTR_ERROR);
    check_context_rejected(&owner, TX_PTR_ERROR);
    range_access_allowed = TX_TRUE;

    check_context_rejected(&unowned, TX_THREAD_ERROR);
    /* MISRA C:2023 Rule 11.6 deviation. The port represents indices as opaque
       pointers. This synthetic value models the first index beyond the pool.  */
    unowned.tx_thread_secure_stack_context = (VOID *) (TX_MAX_SECURE_CONTEXTS + 1U);
    check_context_rejected(&unowned, TX_THREAD_ERROR);
    unowned.tx_thread_secure_stack_context = owner.tx_thread_secure_stack_context;
    check_context_rejected(&unowned, TX_THREAD_ERROR);

    check_stack_save_rejected(test_secure_registers[TEST_REGISTER_PSPLIM] - 1UL, stack_top);
    check_stack_save_rejected(stack_top + 1UL, stack_top);
    assert(_tx_thread_secure_mode_stack_free(&owner) == TX_SUCCESS);
    return(0);
}
